"use strict";(self.webpackChunkeleven_plus_core_concepts=self.webpackChunkeleven_plus_core_concepts||[]).push([[1643],{1643:e=>{e.exports=JSON.parse('{"concept":"Trapezium Area Decomposition","subject":"mathematics","category":"Geometry & Spatial Reasoning","explanation":"Trapeziums (trapezoids) can be split into simpler shapes to find area. Method 1: Split into rectangle + triangle(s). Method 2: Use the trapezium formula: Area = \xbd \xd7 (sum of parallel sides) \xd7 height. Method 1 is often clearer for visualization and checking your work.","examples":[{"question":"A trapezium has parallel sides of 8cm and 12cm, with height 5cm. Find its area by decomposition.","solution":"50 cm\xb2","explanation":"Split into rectangle (8\xd75 = 40 cm\xb2) plus triangle with base (12-8)=4cm and height 5cm. Triangle area = \xbd\xd74\xd75 = 10 cm\xb2. Total: 40 + 10 = 50 cm\xb2."},{"question":"An isosceles trapezium has bases 6cm and 14cm, height 4cm. What\'s the area?","solution":"40 cm\xb2","explanation":"Using decomposition: Rectangle 6\xd74 = 24 cm\xb2. Two identical triangles: each has base (14-6)/2 = 4cm, height 4cm. Each triangle: \xbd\xd74\xd74 = 8 cm\xb2. Total: 24 + 8 + 8 = 40 cm\xb2."},{"question":"A trapezium is formed by cutting off a triangle from a rectangle. If the rectangle was 10\xd76 and the cut triangle has area 12, what\'s the trapezium area?","solution":"48 units\xb2","explanation":"Rectangle area = 10\xd76 = 60. Subtract triangle area: 60 - 12 = 48."}],"exercises":[{"type":"multiple-choice","question":"A trapezium has parallel sides 7cm and 13cm, height 6cm. What\'s its area?","options":["48 cm\xb2","60 cm\xb2","78 cm\xb2","156 cm\xb2"],"correct":[1],"explanation":"Method 1: Rectangle 7\xd76 = 42 cm\xb2, triangle \xbd\xd76\xd76 = 18 cm\xb2. Total: 42 + 18 = 60 cm\xb2. Method 2: \xbd\xd7(7+13)\xd76 = \xbd\xd720\xd76 = 60 cm\xb2."},{"type":"multiple-choice","question":"Which decomposition is most useful for this trapezium: parallel sides 5m and 9m?","options":["Rectangle + triangle","Two triangles","Parallelogram + triangle","Rectangle + two triangles"],"correct":[0],"explanation":"Rectangle (5\xd7height) + triangle (base=9-5=4, same height) is the clearest decomposition for most trapeziums."},{"type":"open-ended","question":"A field is trapezium-shaped with parallel sides 20m and 32m, and perpendicular distance between them 15m. Find the area and explain your method.","sample_answer":"Using decomposition: Rectangle 20\xd715 = 300 m\xb2. Triangle: base=(32-20)=12m, height=15m, so area = \xbd\xd712\xd715 = 90 m\xb2. Total area = 300 + 90 = 390 m\xb2.","explanation":"Decomposition method makes the calculation clear and easy to check."}],"tips":["Split trapezium into rectangle + triangle for clearer working","The triangle has base = difference of parallel sides","Both shapes share the same height","Check using trapezium formula: \xbd(a+b)h","Draw and label your decomposition clearly"]}')}}]);